 14844  /**
 14845   * xmlCtxtReadMemory:
 14846   * @ctxt:  an XML parser context
 14847   * @buffer:  a pointer to a char array
 14848   * @size:  the size of the array
 14849   * @URL:  the base URL to use for the document
 14850   * @encoding:  the document encoding, or NULL
 14851   * @options:  a combination of xmlParserOption
 14852   *
 14853   * Parse an XML in-memory document and build a tree. The input buffer must
 14854   * not contain a terminating null byte.
 14855   * This reuses the existing @ctxt parser context
 14856   *
 14857   * Returns the resulting document tree
 14858   */
 14859  xmlDocPtr
 14860  xmlCtxtReadMemory(xmlParserCtxtPtr ctxt, const char *buffer, int size,
 14861                    const char *URL, const char *encoding, int options)
 14862  {
 14863      xmlParserInputBufferPtr input;
 14864      xmlParserInputPtr stream;
 14865
 14866      if (ctxt == NULL)
 14867          return (NULL);
 14868      if (buffer == NULL)
 14869          return (NULL);
 14870      xmlInitParser();
 14871
 14872      xmlCtxtReset(ctxt);
 14873
 14874      input = xmlParserInputBufferCreateMem(buffer, size, XML_CHAR_ENCODING_NONE);
 14875      if (input == NULL) {
 14876          xmlErrMemory(ctxt, NULL);
 14877          return(NULL);
 14878      }
 14879
 14880      stream = xmlNewIOInputStream(ctxt, input, XML_CHAR_ENCODING_NONE);
 14881      if (stream == NULL) {
 14882          xmlFreeParserInputBuffer(input);
 14883          return(NULL);
 14884      }
 14885
 14886      inputPush(ctxt, stream);
 14887      return (xmlDoRead(ctxt, URL, encoding, options, 1));
 14888  }
